package com.alpharip.staffmod.cases.evidencecaselinker; import java.util.*; public final class EvidenceLinkService {private final LinkedHashMap<String,EvidenceLink> links=new LinkedHashMap<String,EvidenceLink>();public synchronized boolean link(EvidenceLink e){if(e==null)return false;links.put(e.getEvidenceReference(),e);return true;}public synchronized EvidenceLink get(String r){return links.get(r);}public synchronized boolean unlink(String r){return links.remove(r)!=null;}public synchronized List<EvidenceLink> findByCase(String id){List<EvidenceLink> o=new ArrayList<EvidenceLink>();for(EvidenceLink e:links.values())if(e.getCaseId().equalsIgnoreCase(id))o.add(e);return Collections.unmodifiableList(o);}public synchronized List<EvidenceLink> findByReference(String q){List<EvidenceLink> o=new ArrayList<EvidenceLink>();String s=q==null?"":q.toLowerCase(Locale.ROOT);for(EvidenceLink e:links.values())if(e.getEvidenceReference().toLowerCase(Locale.ROOT).contains(s))o.add(e);return Collections.unmodifiableList(o);}public synchronized List<EvidenceLink> getLinks(){return Collections.unmodifiableList(new ArrayList<EvidenceLink>(links.values()));}public synchronized boolean replaceAll(List<EvidenceLink> v){links.clear();if(v!=null)for(EvidenceLink e:v)if(e!=null)links.put(e.getEvidenceReference(),e);return true;}}